const turn = $input.first().json.body;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const ids = ['call_id', 'session_id', 'turn_id', 'correlation_id'];
const valid = object(turn) && turn.schema_version === '1.0' && turn.event_type === 'utterance.final' && ids.every(name => typeof turn[name] === 'string' && turn[name].length > 0 && turn[name].length <= 128) && Number.isInteger(turn.generation_id) && turn.generation_id >= 1 && Number.isInteger(turn.sequence) && turn.sequence >= 1 && typeof turn.timestamp === 'string' && !Number.isNaN(Date.parse(turn.timestamp)) && typeof turn.transcript === 'string' && turn.transcript.trim().length > 0 && turn.transcript.length <= 10000 && ['tr', 'tr-TR'].includes(turn.language) && object(turn.context) && object(turn.caller);
if (!valid) return [{json: {status: 422, response: {error: 'Invalid Voxi schema 1.0 utterance.final turn'}}}];
// Business policy lives only here: acknowledge supplied utterance; no gateway prompt or LLM.
// Long utterances get a short acknowledgement, never truncated quoted speech.
// Stateless deterministic response makes duplicate deliveries idempotent. Do not add side effects
// without a durable store keyed by call_id:turn_id (execution retries/concurrent calls included).
const text = turn.transcript.length <= 4000 ? 'İletiniz alındı. ' + turn.transcript.trim() : 'İletiniz alındı. Mesajınız için teşekkür ederim.';
return [{json: {status: 200, response: {schema_version: '1.0', action: 'speak', text, language: 'tr-TR', voice: 'ema-tr', metadata: {policy: 'turkish-acknowledgement'}, idempotency_key: turn.call_id + ':' + turn.turn_id}}}];
